var CHARMAP={'ß':'ss','æ':'ae','œ':'oe','ø':'o','đ':'d','ł':'l','þ':'th','ð':'d','ħ':'h','ı':'i'};
function deburr(str){
  str=String(str); var out='';
  for(var i=0;i<str.length;i++){
    var ch=str[i], low=ch.toLowerCase();
    if(CHARMAP[ch]!=null) out+=CHARMAP[ch];
    else if(CHARMAP[low]!=null) out+=(ch===low?CHARMAP[low]:CHARMAP[low].toUpperCase());
    else out+=ch;
  }
  if(out.normalize) out=out.normalize('NFKD').replace(/[\u0300-\u036f]/g,'');
  return out;
}
function esc(sep){ return sep.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'); }
